tool_input.command:
mkdir -p migrations/down && cat > migrations/002_product_discount.sql <<'EOF'
set lock_timeout = '5s';
alter table products
  add column discount_percent integer not null default 0
  constraint products_discount_percent_range check (discount_percent between 0 and 100);
EOF
cat > migrations/down/002_product_discount.sql <<'EOF'
alter table products drop column discount_percent;
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('select id, name, price_cents, stock from products','select id, name, price_cents, stock, discount_percent from products')
s=s.replace('''  app.get("/orders"''','''  app.patch("/products/:id", async (req, res) => {
    if (res.locals.user.role !== "admin") return sendError(res, 403, "forbidden", "Admin only");
    const id = Number(req.params.id);
    if (!Number.isSafeInteger(id) || id < 1 || id > 2147483647) {
      return sendError(res, 400, "invalid_id", "Product id must be a positive integer");
    }
    const discountPercent = req.body?.discountPercent;
    if (!Number.isInteger(discountPercent) || discountPercent < 0 || discountPercent > 100) {
      return sendError(res, 400, "invalid_discount", "discountPercent must be a whole number from 0 to 100");
    }
    const { rows } = await pool.query(
      "update products set discount_percent = $1 where id = $2 returning id, name, price_cents, stock, discount_percent",
      [discountPercent, id],
    );
    if (rows.length === 0) return sendError(res, 404, "not_found", "Product not found");
    res.json(rows[0]);
  });

  app.get("/orders"''',1)
open(p,'w').write(s)
p='postman/shop-api.postman_collection.json'
s=open(p).read()
s=s.replace('''    { "name": "List my orders"''','''    { "name": "Set product discount (admin)", "request": { "method": "PATCH", "header": [{ "key": "Content-Type", "value": "application/json" }], "url": "{{baseUrl}}/products/1", "body": { "mode": "raw", "raw": "{ \\"discountPercent\\": 20 }" } } },
    { "name": "List my orders"''')
open(p,'w').write(s)
EOF
cat >> test/app.test.ts <<'EOF'

const patchDiscount = (token: string, id: string | number, body: unknown) =>
  fetch(`${base}/products/${id}`, {
    method: "PATCH",
    headers: { ...as(token), "content-type": "application/json" },
    body: JSON.stringify(body),
  });

test("admin can set a product discount; it shows in /products", async () => {
  const res = await patchDiscount("admin-token", 1, { discountPercent: 25 });
  assert.equal(res.status, 200);
  assert.equal((await res.json()).discount_percent, 25);
  const products = await (await fetch(`${base}/products`, { headers: as("alice-token") })).json();
  assert.equal(products.find((p: { id: number }) => p.id === 1).discount_percent, 25);
});

test("non-admin cannot set a discount", async () => {
  const res = await patchDiscount("alice-token", 1, { discountPercent: 10 });
  assert.equal(res.status, 403);
});

test("bad discount input is a 400; unknown product is a 404", async () => {
  for (const bad of [{}, { discountPercent: -1 }, { discountPercent: 101 }, { discountPercent: 1.5 }, { discountPercent: "10" }]) {
    assert.equal((await patchDiscount("admin-token", 1, bad)).status, 400);
  }
  assert.equal((await patchDiscount("admin-token", "abc", { discountPercent: 5 })).status, 400);
  assert.equal((await patchDiscount("admin-token", 99999, { discountPercent: 5 })).status, 404);
});
EOF
pnpm typecheck 2>&1 | tail -5; pnpm test 2>&1 | tail -25
